// Normalize, Filter Prefix (!N / !notes / !todo), and Deduplicate Notes
const items = $input.all();
const now = new Date();
const dateStr = now.toISOString().split('T')[0];

function normalizeText(text) {
  if (!text) return '';
  return text.toLowerCase()
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/[^\w\sąćęłńóśźż]/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripPrefix(content) {
  if (!content) return { isValid: false, cleanText: '' };
  const pattern = /^\s*!(n|notes|note|todo|task)\b[:\s]*/i;
  const match = content.match(pattern);
  if (match) {
    return { isValid: true, cleanText: content.substring(match[0].length).trim() };
  }
  return { isValid: false, cleanText: content.trim() };
}

function isNearDuplicate(norm1, norm2, threshold = 0.70) {
  if (norm1 === norm2) return true;
  if (norm1.includes(norm2) || norm2.includes(norm1)) {
    const minLen = Math.min(norm1.length, norm2.length);
    const maxLen = Math.max(norm1.length, norm2.length);
    if (minLen / maxLen >= 0.60) return true;
  }
  const words1 = new Set(norm1.split(' ').filter(Boolean));
  const words2 = new Set(norm2.split(' ').filter(Boolean));
  if (words1.size === 0 || words2.size === 0) return false;

  let intersection = 0;
  for (const w of words1) {
    if (words2.has(w)) intersection++;
  }
  const union = new Set([...words1, ...words2]).size;
  const jaccard = union > 0 ? intersection / union : 0;
  if (jaccard >= threshold) return true;

  const shorter = words1.size <= words2.size ? words1 : words2;
  const longer = words1.size <= words2.size ? words2 : words1;
  let allContained = true;
  for (const w of shorter) {
    if (!longer.has(w)) {
      allContained = false;
      break;
    }
  }
  if (allContained && shorter.size >= 3) return true;

  return false;
}

function classifyNote(text) {
  const lower = text.toLowerCase();
  const todoKeywords = ['todo', 'task', 'zadanie', 'kupić', 'buy', 'fix', 'napraw', 'call', 'zadzwoń', 'deadline', 'wysłać', 'send', 'review'];
  const ideaKeywords = ['idea', 'pomysł', 'concept', 'koncepcja', 'brainstorm', 'feature', 'think about', 'rozważyć'];
  if (todoKeywords.some(kw => lower.includes(kw)) || lower.startsWith('- [ ]')) return 'TODO';
  if (ideaKeywords.some(kw => lower.includes(kw))) return 'Idea';
  return 'Note';
}

// Extract raw message list
let rawList = [];
for (const item of items) {
  const data = item.json;
  if (Array.isArray(data)) {
    rawList.push(...data);
  } else if (data.data && Array.isArray(data.data)) {
    rawList.push(...data.data);
  } else if (data.messages && Array.isArray(data.messages)) {
    rawList.push(...data.messages);
  } else if (data.content || data.body || data.text) {
    rawList.push(data);
  }
}

// Fallback sample data if no Discord credentials provided during test execution
if (rawList.length === 0 || (rawList.length === 1 && rawList[0].error)) {
  rawList = [
    { content: "!N Review pull request for authentication microservice", author: { username: "Kacper" }, timestamp: now.toISOString() },
    { content: "!N review pull request for authentication microservice!", author: { username: "Kacper" }, timestamp: now.toISOString() },
    { content: "!notes Idea: Build automated Discord secretary with deduplication for Obsidian", author: { username: "Kacper" }, timestamp: now.toISOString() },
    { content: "!todo Kupić chleb, masło i kawę", author: { username: "Kacper" }, timestamp: now.toISOString() },
    { content: "!n kupić chleb, masło i kawę", author: { username: "Kacper" }, timestamp: now.toISOString() },
    { content: "!N Schedule dentist appointment for next Tuesday at 14:00", author: { username: "Kacper" }, timestamp: now.toISOString() },
    { content: "Hey anyone online playing games tonight?", author: { username: "Friend" }, timestamp: now.toISOString() }
  ];
}

const acceptedNotes = [];
let duplicateCount = 0;
let expiredCount = 0;
const twentyFourHoursAgo = now.getTime() - 24 * 60 * 60 * 1000;

for (const msg of rawList) {
  const rawText = msg.content || msg.text || msg.body || '';
  const authorName = (msg.author && msg.author.username) || msg.user || 'Kacper';
  const timestamp = msg.timestamp || msg.created_at || now.toISOString();

  // 1. 24-Hour Cutoff: Discard notes from previous days / older than 24 hours
  const msgTime = new Date(timestamp).getTime();
  if (!isNaN(msgTime) && msgTime < twentyFourHoursAgo) {
    expiredCount++;
    continue;
  }

  const { isValid, cleanText } = stripPrefix(rawText);
  if (!isValid || !cleanText) continue;

  const norm = normalizeText(cleanText);
  let isDup = false;

  for (const existing of acceptedNotes) {
    if (isNearDuplicate(norm, existing.normalized)) {
      if (cleanText.length > existing.cleanText.length) {
        existing.cleanText = cleanText;
        existing.normalized = norm;
        existing.category = classifyNote(cleanText);
      }
      isDup = true;
      break;
    }
  }

  if (isDup) {
    duplicateCount++;
    continue;
  }

  acceptedNotes.push({
    author: authorName,
    rawText,
    cleanText,
    normalized: norm,
    category: classifyNote(cleanText),
    timestamp
  });
}

// Prepare prompt context
let promptContext = `Date: ${dateStr}\nUser: Kacper\nProcessed Notes count: ${acceptedNotes.length}\nDuplicates eliminated: ${duplicateCount}\nOlder than 24h skipped: ${expiredCount}\n\nRAW ITEMS:\n`;
acceptedNotes.forEach((n, idx) => {
  promptContext += `${idx + 1}. [${n.category}] ${n.cleanText} (Logged at ${n.timestamp.substring(11, 16)})\n`;
});

return [{
  json: {
    dateStr,
    timestamp: now.toISOString(),
    totalReceived: rawList.length,
    totalAccepted: acceptedNotes.length,
    duplicateCount,
    expiredCount,
    acceptedNotes,
    promptContext
  }
}];

