// Build Discord Rich Embed & Obsidian Markdown Note
const prevData = $('Deduplication & Notes Parser').first().json;
const aiResponse = $input.first() ? $input.first().json : {};
const dateStr = prevData.dateStr;
const notes = prevData.acceptedNotes || [];

let aiParsed = null;
try {
  if (aiResponse.candidates && aiResponse.candidates[0]?.content?.parts[0]?.text) {
    aiParsed = JSON.parse(aiResponse.candidates[0].content.parts[0].text);
  }
} catch (e) {
  aiParsed = null;
}

// Fallback categorization if AI call skipped or unconfigured
const todos = aiParsed?.todos || notes.filter(n => n.category === 'TODO').map(n => n.cleanText);
const ideas = aiParsed?.ideas || notes.filter(n => n.category === 'Idea').map(n => n.cleanText);
const generalNotes = aiParsed?.notes || notes.filter(n => n.category === 'Note').map(n => n.cleanText);
const summaryText = aiParsed?.summary || `Hey Kacper! I've processed your stream of notes from the last 24 hours (${prevData.totalAccepted} unique items saved, ${prevData.duplicateCount} duplicates eliminated${prevData.expiredCount > 0 ? `, ${prevData.expiredCount} older notes skipped` : ''}). Here is your organized digest!`;

// 1. Build Discord Embed Fields
const discordFields = [];

if (todos.length > 0) {
  discordFields.push({
    name: "📋 Actionable Tasks & TODOs",
    value: todos.slice(0, 8).map(t => `• [ ] ${t}`).join('\n'),
    inline: false
  });
} else {
  discordFields.push({
    name: "📋 Actionable Tasks & TODOs",
    value: "*No pending tasks recorded today.*",
    inline: false
  });
}

if (ideas.length > 0) {
  discordFields.push({
    name: "💡 Ideas & Brainstorms",
    value: ideas.slice(0, 6).map(i => `• 💡 ${i}`).join('\n'),
    inline: false
  });
}

if (generalNotes.length > 0) {
  discordFields.push({
    name: "📝 General Notes & Insights",
    value: generalNotes.slice(0, 6).map(n => `• ${n}`).join('\n'),
    inline: false
  });
}

const discordEmbed = {
  embeds: [
    {
      title: `🌸 Baizhi Daily Executive Digest — ${dateStr}`,
      description: summaryText,
      color: 10181046, // #9B59B6 Purple
      fields: discordFields,
      footer: {
        text: `Baizhi AI Assistant • ${prevData.totalAccepted} Today's Notes • ${prevData.duplicateCount} Dupes Filtered`
      },
      timestamp: new Date().toISOString()
    }
  ]
};

// Plain-text digest for the Discord send node (2000 char limit)
const list = (arr) => arr.length ? arr.map(x => `- ${x}`).join('\n') : '*none*';
const discordText = [
  `**Baizhi Daily Executive Digest - ${dateStr}**`,
  summaryText,
  `**TODOs**\n${list(todos)}`,
  `**Ideas**\n${list(ideas)}`,
  `**Notes**\n${list(generalNotes)}`
].join('\n\n').substring(0, 1990);

return [{
  json: {
    dateStr,
    discordPayload: discordEmbed,
    discordText
  }
}];
